package adobe
import("os";"path/filepath";"strings";"testing";"encoding/json")
func TestDiagnosticRedaction(t *testing.T){p:=filepath.Join(t.TempDir(),"events");t.Setenv("ADOBE_DIAG_FILE",p);done:=diagHTTP(&Request{Method:"POST",URL:"https://example.test/ims/token/v3?secret=QUERY_SECRET",Headers:map[string]string{"Authorization":"Bearer TOKEN_SECRET","Cookie":"COOKIE_SECRET"},Body:[]byte(`{"prompt":"PROMPT_SECRET","model":"test"}`)},"http://USER_SECRET:PASSWORD_SECRET@proxy");done(&Response{StatusCode:401,Body:[]byte(`{"error":"invalid_credentials"}`),SetCookies:[]string{"SESSION_SECRET"}},nil);b,e:=os.ReadFile(p);if e!=nil{t.Fatal(e)};for _,s:=range []string{"QUERY_SECRET","TOKEN_SECRET","COOKIE_SECRET","PROMPT_SECRET","USER_SECRET","PASSWORD_SECRET","SESSION_SECRET"}{if strings.Contains(string(b),s){t.Fatal("secret leaked",s)}};for _,l:=range strings.Split(strings.TrimSpace(string(b)),"\n"){var d map[string]any;if json.Unmarshal([]byte(l),&d)!=nil{t.Fatal("invalid JSON")}}}
